script:
(function () {
  'use strict';
  // Annual return implied by a single lump sum P growing (or shrinking) to an ending value E over
  // t years (years + months / 12), with no deposits or withdrawals in between:
  //   R = (E / P)^(1/t) - 1   (compound annual growth rate, compounded once a year)
  // Same growth quoted other ways: compounded monthly 12 x ((1 + R)^(1/12) - 1), daily
  // 365 x ((1 + R)^(1/365) - 1), continuously ln(1 + R). Years to double = ln 2 / ln(1 + R).
  // Comparison table: ending value at another annual return x = P x (1 + x)^t.
  // CHECKS (Node, scratch tests/ls.test.js): $10,000 -> $20,000 in 10 years = 7.1773% a year
  // (2^(1/10) - 1) and doubles in exactly 10.0 years; $10,000 -> $15,000 in 5 years = 8.4472%;
  // $10,000 -> $10,000 = 0%; $10,000 -> $8,000 in 2 years = -10.5573%; 18 months 1,000 -> 1,200
  // = 12.9243%; 8.4472% compounded monthly quotes as 8.1368% and continuously as 8.1093% (ln 1.5 / 5);
  // re-growing $10,000 at the implied rate for the period returns the ending value exactly.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var COMPARE = [-0.04, -0.02, 0, 0.02, 0.04, 0.06, 0.08, 0.10, 0.12, 0.15];
  var IDS = ['lsRate', 'lsTotal', 'lsGain', 'lsMultiple', 'lsMonthly', 'lsDaily', 'lsContinuous', 'lsDouble'];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }
  function signed(x) { return (x < 0 ? '−' : x > 0 ? '+' : '') + money.format(Math.abs(x)); }
  function nominal(R, n) { return n * (Math.pow(1 + R, 1 / n) - 1); }

  function implied(P, E, t) { return E > 0 ? Math.pow(E / P, 1 / t) - 1 : -1; }

  function growthRows(P, R, t) {
    var rows = [], bal = P, whole = Math.floor(t + 1e-9), rest = t - whole;
    for (var y = 1; y <= whole; y++) {
      var end = P * Math.pow(1 + R, y);
      rows.push({ label: String(y), start: bal, end: end });
      bal = end;
    }
    if (rest > 1e-9) rows.push({ label: (whole + rest).toFixed(2).replace(/0$/, ''), start: bal, end: P * Math.pow(1 + R, t) });
    return rows;
  }

  function clear(msg) {
    var error = document.getElementById('lsError');
    error.hidden = !msg;
    error.textContent = msg;
    IDS.forEach(function (id) { set(id, '–'); });
    set('lsSummary', '');
    document.getElementById('lsCompare').innerHTML = '';
    document.getElementById('lsSchedule').innerHTML = '';
  }

  function update() {
    var P = num('lsStart'), E = num('lsEnd'), yrs = num('lsYears'), mos = num('lsMonths');
    if (isNaN(mos)) mos = 0;
    if (isNaN(yrs)) yrs = 0;
    var t = Math.round(yrs) + Math.round(mos) / 12;
    if (isNaN(P) || P <= 0) return clear('Enter an amount invested above $0.');
    if (isNaN(E) || E < 0) return clear('Enter an ending value of $0 or more.');
    if (yrs < 0 || mos < 0 || mos > 11 || yrs > 100 || t < 1 / 12) return clear('Enter a holding period of at least one month (0 to 100 years and 0 to 11 months).');
    document.getElementById('lsError').hidden = true;

    var R = implied(P, E, t), lost = R <= -1;
    set('lsRate', pct(R, 2));
    set('lsTotal', pct(E / P - 1, 2));
    set('lsGain', signed(E - P));
    set('lsMultiple', (E / P).toFixed(2) + '×');
    set('lsMonthly', lost ? '–' : pct(nominal(R, 12), 2));
    set('lsDaily', lost ? '–' : pct(nominal(R, 365), 2));
    set('lsContinuous', lost ? '–' : pct(Math.log(1 + R), 2));
    set('lsDouble', R > 0 ? (Math.log(2) / Math.log(1 + R)).toFixed(1) + ' years' : 'Never at this rate');
    var period = (Math.round(yrs) ? Math.round(yrs) + (Math.round(yrs) === 1 ? ' year' : ' years') : '') +
                 (Math.round(yrs) && Math.round(mos) ? ' and ' : '') +
                 (Math.round(mos) ? Math.round(mos) + (Math.round(mos) === 1 ? ' month' : ' months') : '');
    set('lsSummary', 'Turning ' + money.format(P) + ' into ' + money.format(E) + ' over ' + period +
        ' works out to ' + pct(R, 2) + ' a year, compounded annually.');

    var list = COMPARE.map(function (x) { return { rate: x, yours: false }; });
    var match = list.filter(function (it) { return Math.abs(it.rate - R) < 5e-5; })[0];
    if (match) match.yours = true; else list.push({ rate: R, yours: true });
    list.sort(function (a, b) { return a.rate - b.rate; });
    var tbody = document.getElementById('lsCompare');
    tbody.textContent = '';
    list.forEach(function (it) {
      var end = it.yours ? E : P * Math.pow(1 + it.rate, t), tr = document.createElement('tr');
      [pct(it.rate, 2), money.format(end), signed(end - P), it.yours ? '–' : signed(end - E)].forEach(function (text, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = text;
        if (i === 0 && it.yours) {
          var b = document.createElement('span');
          b.className = 'badge badge-sky ml-2';
          b.textContent = 'Your result';
          td.appendChild(b);
        }
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });

    document.getElementById('lsSchedule').innerHTML = growthRows(P, R, t).map(function (row) {
      return '<tr><td>' + row.label + '</td><td>' + money.format(row.start) + '</td><td>' + signed(row.end - row.start) +
             '</td><td>' + money.format(row.end) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('lsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
